const homeLabels: Record<L,string>={en:"Home",de:"Startseite",fr:"Accueil",es:"Inicio",it:"Home",pt:"Início",nl:"Home",pl:"Strona główna",sv:"Hem"};
function LegacyHome(){
 const [lang,setLang]=useState<L>("en"),t=d[lang],db="https://findspreadsheet.com/";
 return <main><header className="site-header"><a className="brand logo-link" href="#top"><img src="/lolobuy-logo.png" alt="LoloBuy" className="logo-image"/></a><nav>{t.nav.map((x,i)=><a key={x} href={["#top","#regions","#process","#directory"][i]}>{i===0?homeLabels[lang]:x}</a>)}</nav><label className="language-select"><span>{t.choose}</span><select value={lang} onChange={e=>setLang(e.target.value as L)} aria-label={t.choose}>{langs.map(x=><option key={x.id} value={x.id}>{x.short} · {x.name}</option>)}</select></label></header>
 <section className="hero" id="top"><img src="/research-hero-approved.jpg" alt="People comparing unbranded style research cards in a studio"/><div className="hero-shade"/><div className="hero-copy" id="research"><p className="kicker">{t.tag}</p><h1>{t.title}</h1><p className="hero-lead">{t.lead}</p><div className="hero-actions"><a className="button button-primary" href={db}>{t.open}<span>↗</span></a><form className="search-form" action="https://findspreadsheet.com/search.html" method="get"><input name="keywords" placeholder={t.explore} aria-label={t.explore} required/><input type="hidden" name="channelid" value="2"/><button type="submit" aria-label={t.explore}>⌕</button></form></div><ul className="proof">{t.proof.map((x,i)=><li key={x}><b>0{i+1}</b>{x}</li>)}</ul></div><p className="hero-caption">LoloBuy Sheet FR / {t.tag}</p></section>
 <section className="section market" id="regions"><div className="section-intro"><p className="kicker blue">{t.lens[0]}</p><h2>{t.lens[1]}</h2><p>{t.lens[2]}</p></div><div className="region-grid">{regions.map(([code,name,locale],i)=><article className="region" key={code}><span>{String(i+1).padStart(2,"0")}</span><b>{code}</b><p>{name}</p><small>{locale}</small></article>)}</div></section>
 <section className="section route-section" id="process"><div className="route-panel"><p className="kicker coral">{t.route[0]}</p><h2>{t.route[1]}</h2><p>{t.route[2]}</p><ol>{t.steps.map((x,i)=><li key={x}><span>0{i+1}</span>{x}</li>)}</ol></div><aside className="route-aside"><p>{t.route[0]}</p>{t.steps.map((x,i)=><div key={x}><b>0{i+1}</b><span>{x}</span></div>)}</aside></section>
 <section className="section catalog" id="directory"><div className="catalog-copy"><p className="kicker blue">{t.dir[0]}</p><h2>{t.dir[1]}</h2><p>{t.dir[2]}</p><a className="button button-primary" href={db}>{t.dir[3]}<span>↗</span></a></div><div className="category-grid">{t.cats.map((x,i)=><a key={x} href={db} className="category-card"><span>{String(i+1).padStart(2,"0")}</span><strong>{x}</strong><i>↗</i></a>)}</div></section>
 <section className="section reading"><p className="kicker coral">{t.route[0]}</p><h2>{t.editorial[0]}</h2><div className="reading-grid">{t.editorial.map((x,i)=><article key={x}><span>0{i+1}</span><h3>{x}</h3><p>{t.notes[i]}</p></article>)}</div></section>
 <section className="final-cta"><div><p className="kicker">FINDSPREADSHEET</p><h2>{t.final[0]}</h2><p>{t.final[1]}</p></div><a className="button button-light" href={db}>{t.final[2]}<span>↗</span></a></section>
 <footer><a className="brand logo-link" href="#top"><img src="/lolobuy-logo.png" alt="LoloBuy" className="logo-image"/></a><p>{t.disc}</p><div className="footer-languages">{langs.map(x=><button key={x.id} onClick={()=>setLang(x.id)} className={lang===x.id?"active":""}>{x.short}</button>)}</div></footer></main>;
}

